package ru.local.spbumailpilot;
import javax.mail.*;import javax.mail.internet.*;import java.util.*;import org.json.*;
public class MailAttachmentsTest {
 static void check(boolean v){if(!v)throw new AssertionError();}
 static MimeBodyPart pdf()throws Exception{MimeBodyPart p=new MimeBodyPart(){public Object getContent(){throw new AssertionError("binary payload fetched");}public java.io.InputStream getInputStream(){throw new AssertionError("binary downloaded");}};p.setHeader("Content-Type","application/pdf");p.setFileName("Материалы.pdf");return p;}
 public static void main(String[] args)throws Exception{Session session=Session.getInstance(new Properties());MimeMessage message=new MimeMessage(session);MimeMultipart alternative=new MimeMultipart("alternative");MimeBodyPart plain=new MimeBodyPart();plain.setText("Коллеги, материалы на завтра");alternative.addBodyPart(plain);MimeBodyPart branch=new MimeBodyPart();MimeMultipart related=new MimeMultipart("related");MimeBodyPart html=new MimeBodyPart();html.setContent("<p>Материалы</p>","text/html");related.addBodyPart(html);related.addBodyPart(pdf());branch.setContent(related);alternative.addBodyPart(branch);message.setContent(alternative);message.saveChanges();JSONArray files=MailAttachments.list(message);check(files.length()==1&&files.getJSONObject(0).getString("path").equals("1.1"));check(AttachmentParts.resolve(message,"1.1")==related.getBodyPart(1));
  MimeBodyPart forward=new MimeBodyPart(){public Object getContent(){throw new AssertionError("forwarded payload decoded");}};forward.setHeader("Content-Type","message/rfc822");check(MailAttachments.list(forward).getJSONObject(0).getString("name").endsWith(".eml"));check(AttachmentParts.resolve(forward,"root")==forward);
  MimeBodyPart image=new MimeBodyPart();image.setHeader("Content-Type","image/png");image.setFileName("logo.png");image.setDisposition(Part.INLINE);check(MailAttachments.list(image).length()==0);image.setDisposition(Part.ATTACHMENT);check(MailAttachments.list(image).length()==1);
  ReadFlagTest.MemoryStore store=new ReadFlagTest.MemoryStore(session);store.folder.message.setContent(alternative);store.folder.message.saveChanges();MailReader reader=new MailReader();java.lang.reflect.Field field=MailReader.class.getDeclaredField("store");field.setAccessible(true);field.set(reader,store);JSONObject body=reader.body("INBOX","42","7");check(body.getString("text").contains("материалы")&&body.getJSONArray("attachments").length()==1);check(!store.folder.message.isSet(Flags.Flag.SEEN));ReadFlagTest.MemoryStore plainStore=new ReadFlagTest.MemoryStore(session);plainStore.folder.message.setRecipients(Message.RecipientType.BCC,"hidden@example.invalid");plainStore.folder.message.saveChanges();MailReader exporter=new MailReader();field.set(exporter,plainStore);java.nio.file.Path temp=java.nio.file.Files.createTempDirectory("forward-test");JSONObject exported=exporter.exportMessage("INBOX","42","7",temp.toFile(),true);try(java.io.InputStream input=new java.io.FileInputStream(exported.getString("file"))){MimeMessage forwarded=new MimeMessage(session,input);check(forwarded.getRecipients(Message.RecipientType.BCC)==null);check(forwarded.getFrom().length==1);}check(plainStore.folder.message.getRecipients(Message.RecipientType.BCC).length==1);java.nio.file.Files.delete(java.nio.file.Paths.get(exported.getString("file")));java.nio.file.Files.delete(temp);check(UniversityDirectory.prefixFilter("П").contains("cn=П*"));try{UniversityDirectory.prefixFilter("П*)");throw new AssertionError();}catch(IllegalArgumentException expected){}
  System.out.println("PASS: attachments in non-selected alternative branch, valid MIME paths, inline vs downloadable images, RFC822 metadata without payload, read-only body and bounded directory prefix filter.");
 }
}
